package im.nexar.jarvis;

import android.content.*;
import android.media.AudioManager;
import android.view.KeyEvent;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.cert.X509Certificate;
import java.util.*;
import java.util.concurrent.*;
import javax.net.ssl.*;
import org.json.*;

/** Network boundary for the desktop and Supabase.  No bearer token is kept in ordinary prefs. */
public final class DesktopApi {
  static final String DEFAULT_VOICE="de-DE-ConradNeural", DEFAULT_CITY="Wien";
  final Context c; final SharedPreferences p; final SecureStore secure;
  String cloudUrl, anonKey; ScheduledExecutorService poller;
  private final Object syncLock=new Object(); private boolean syncInFlight;
  DesktopApi(Context c, SharedPreferences p){this.c=c;this.p=p;secure=new SecureStore(c,p);loadCloud();}
  private void loadCloud(){try(InputStream in=c.getAssets().open("cloud.json")){JSONObject j=new JSONObject(read(in));cloudUrl=j.optString("url").replaceAll("/$","");anonKey=j.optString("anonKey");}catch(Exception e){cloudUrl="";anonKey="";}}
  private static String read(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] z=new byte[8192];int n;while((n=in.read(z))!=-1)b.write(z,0,n);return b.toString("UTF-8");}
  static final class R{final int code;final String body;R(int c,String b){code=c;body=b;}}
  static final class Voice{final String shortName,locale,gender,friendlyName;Voice(String s,String l,String g,String f){shortName=s;locale=l;gender=g;friendlyName=f;}String label(){String name=shortName.replaceAll("^.*-([^-]+)Neural$","$1");return name+" · "+Locale.forLanguageTag(locale).getDisplayName(Locale.GERMAN)+" · "+gender;}}
  static final class SpeakResult{final byte[] audio;final String mime;SpeakResult(byte[]a,String m){audio=a;mime=m;}}
  interface VoiceCallback{void done(List<Voice>v,String e);} interface SpeakCallback{void done(SpeakResult r,String e);} interface MediaCallback{void done(String e);}

  private R http(String method,String raw,String body,Map<String,String> h,SSLSocketFactory sf,HostnameVerifier hv){HttpsURLConnection x=null;try{URL u=new URL(raw);if(!"https".equalsIgnoreCase(u.getProtocol()))return new R(0,"HTTPS erforderlich");x=(HttpsURLConnection)u.openConnection();x.setInstanceFollowRedirects(false);if(sf!=null)x.setSSLSocketFactory(sf);if(hv!=null)x.setHostnameVerifier(hv);x.setRequestMethod(method);x.setConnectTimeout(9000);x.setReadTimeout(9000);x.setUseCaches(false);x.setRequestProperty("Accept","application/json");if(h!=null)for(Map.Entry<String,String> e:h.entrySet())x.setRequestProperty(e.getKey(),e.getValue());if(body!=null){x.setDoOutput(true);x.setRequestProperty("Content-Type","application/json");try(OutputStream o=x.getOutputStream()){o.write(body.getBytes(StandardCharsets.UTF_8));}}int code=x.getResponseCode();InputStream in=code<400?x.getInputStream():x.getErrorStream();return new R(code,in==null?"":read(in));}catch(Exception e){return new R(0,e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());}finally{if(x!=null)x.disconnect();}}
  private R desktop(String method,String path,String body){try{URL base=new URL(p.getString("baseUrl",""));String fp=p.getString("fingerprint","").replace(":","").toLowerCase(Locale.US);if(!"https".equalsIgnoreCase(base.getProtocol())||!fp.matches("[0-9a-f]{64}"))return new R(0,"Desktop-Pin ungültig");final String host=base.getHost();TrustManager[] tm={new X509TrustManager(){public X509Certificate[]getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[]a,String b){}public void checkServerTrusted(X509Certificate[]a,String b)throws java.security.cert.CertificateException{if(a==null||a.length==0)throw new java.security.cert.CertificateException("Kein Zertifikat");try{byte[] d=MessageDigest.getInstance("SHA-256").digest(a[0].getEncoded());if(!MessageDigest.isEqual(d,hex(fp)))throw new java.security.cert.CertificateException("Zertifikat-Pin stimmt nicht");}catch(java.security.cert.CertificateException e){throw e;}catch(Exception e){throw new java.security.cert.CertificateException(e);}}}};SSLContext sc=SSLContext.getInstance("TLS");sc.init(null,tm,new SecureRandom());Map<String,String> h=new HashMap<>();String t=secure.get("token");if(!t.isEmpty())h.put("Authorization","Bearer "+t);return http(method,new URL(base,path).toString(),body,h,sc.getSocketFactory(),(n,s)->host.equalsIgnoreCase(n));}catch(Exception e){return new R(0,"Desktop-Verbindung fehlgeschlagen");}}
  private static byte[] hex(String s){byte[]b=new byte[s.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(s.substring(i*2,i*2+2),16);return b;}
  boolean isPaired(){return !p.getString("baseUrl","").isEmpty()&&!secure.get("token").isEmpty();}

  String pair(String invite){String oldUrl=p.getString("baseUrl","");String oldFp=p.getString("fingerprint","");String oldToken=secure.get("token");try{JSONObject j=new JSONObject(new String(Base64.getUrlDecoder().decode(invite.trim()),StandardCharsets.UTF_8));String url=j.getString("url"),fp=j.getString("fingerprint").replace(":","").toLowerCase(Locale.US),secret=j.getString("secret");if(!url.startsWith("https://")||!fp.matches("[0-9a-f]{64}"))return "Einladung ungültig";p.edit().putString("baseUrl",url.replaceAll("/$","")).putString("fingerprint",fp).apply();R r=desktop("POST","/pair",new JSONObject().put("secret",secret).put("name","Jarvis Android").toString());if(r.code<200||r.code>=300)throw new Exception(error(r));JSONObject x=new JSONObject(r.body);String tok=x.optString("token");if(tok.isEmpty())throw new Exception("Kein Desktop-Token");secure.put("token",tok);return "Desktop verbunden";}catch(Exception e){p.edit().putString("baseUrl",oldUrl).putString("fingerprint",oldFp).apply();if(oldToken.isEmpty())secure.remove("token");else secure.put("token",oldToken);return "Einladung ungültig oder Kopplung fehlgeschlagen";}}

  void media(String a,MediaCallback cb){new Thread(()->{String err=null;if(isPaired()){R r=desktop("POST","/media",json("action",a));if(r.code<200||r.code>=300)err=error(r);}else{AudioManager m=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);if("volumeup".equals(a))m.adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_RAISE,AudioManager.FLAG_SHOW_UI);else if("volumedown".equals(a))m.adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_LOWER,AudioManager.FLAG_SHOW_UI);else if("mute".equals(a))m.adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_TOGGLE_MUTE,AudioManager.FLAG_SHOW_UI);else{int k="playpause".equals(a)?KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE:"next".equals(a)?KeyEvent.KEYCODE_MEDIA_NEXT:"previous".equals(a)?KeyEvent.KEYCODE_MEDIA_PREVIOUS:"stop".equals(a)?KeyEvent.KEYCODE_MEDIA_STOP:0;if(k==0)err="Unbekannte Medienaktion";else{m.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,k));m.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,k));}}}if(cb!=null)cb.done(err);}).start();}
  void voices(VoiceCallback cb){if(!isPaired()){cb.done(Collections.emptyList(),"Für Microsoft-Stimmen mit PC koppeln");return;}new Thread(()->{R r=desktop("GET","/voices",null);try{if(r.code<200||r.code>=300)throw new Exception(error(r));JSONArray a=new JSONArray(r.body);List<Voice>o=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject j=a.getJSONObject(i);String sn=j.optString("ShortName"),loc=j.optString("Locale"),g=j.optString("Gender");String name=j.optString("FriendlyName");if(name.isEmpty()&&loc.contains("-")){try{name=loc+" · "+Locale.forLanguageTag(loc).getDisplayName(Locale.GERMAN);}catch(Exception ignored){}}String gender="Male".equalsIgnoreCase(g)?"männlich":"Female".equalsIgnoreCase(g)?"weiblich":g;o.add(new Voice(sn,loc,gender,name.isEmpty()?sn:name));}cb.done(o,null);}catch(Exception e){cb.done(Collections.emptyList(),e.getMessage());}}).start();}

  String weather(String city){if(city==null||city.trim().isEmpty())return "Ungültiger Wetterort";try{String q=URLEncoder.encode(city.trim(),"UTF-8");R g=http("GET","https://geocoding-api.open-meteo.com/v1/search?name="+q+"&count=1&language=de&format=json",null,null,null,null);if(g.code<200||g.code>=300) return "Wetter nicht verfügbar: "+error(g);JSONObject gj=new JSONObject(g.body);JSONArray rs=gj.optJSONArray("results");if(rs==null||rs.length()==0)return "Wetterort nicht gefunden";JSONObject place=rs.getJSONObject(0);double lat=place.getDouble("latitude"),lon=place.getDouble("longitude");String u="https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,weather_code,wind_speed_10m&temperature_unit=celsius&wind_speed_unit=kmh&forecast_days=1";R w=http("GET",u,null,null,null,null);if(w.code<200||w.code>=300)return "Wetter nicht verfügbar: "+error(w);JSONObject cur=new JSONObject(w.body).getJSONObject("current");return String.format(Locale.GERMAN,"Wetter · %s: %.1f °C · %s · Wind %.0f km/h",city.trim(),cur.getDouble("temperature_2m"),weatherCode(cur.getInt("weather_code")),cur.getDouble("wind_speed_10m"));}catch(Exception e){return "Wetter nicht verfügbar: "+e.getMessage();}}
  private String weatherCode(int n){if(n==0)return "klar";if(n<=3)return "teilweise bewölkt";if(n<=48)return "neblig";if(n<=57)return "Nieselregen";if(n<=67)return "Regen";if(n<=77)return "Schnee";if(n<=82)return "Regenschauer";if(n<=86)return "Schneeschauer";return "Gewitter";}

  void startPolling(Runnable done){stopPolling();poller=Executors.newSingleThreadScheduledExecutor();poller.scheduleWithFixedDelay(()->{if(isPaired()){R r=desktop("GET","/state",null);if(r.code>=200&&r.code<300&&done!=null)done.run();}if(hasCloudSession())syncSettings();},0,30,TimeUnit.SECONDS);}
  void stopPolling(){if(poller!=null){poller.shutdownNow();poller=null;}}
  String cloudStatus(){String e=secure.get("email");return hasCloudSession()?(e.isEmpty()?"Angemeldet":e):"Nicht angemeldet";}
  boolean isSignedIn(){return hasCloudSession();}
  private boolean hasCloudSession(){return !secure.get("accessToken").isEmpty()&&!secure.get("refreshToken").isEmpty()&&!secure.get("userId").isEmpty();}
  private Map<String,String> headers(){if(!refreshSessionIfNeeded())throw new IllegalStateException("Anmeldung momentan nicht verfügbar");Map<String,String>h=new HashMap<>();h.put("apikey",anonKey);String t=secure.get("accessToken");if(!t.isEmpty())h.put("Authorization","Bearer "+t);return h;}
  private boolean refreshSessionIfNeeded(){try{long exp=Long.parseLong(secure.get("expiresAt"));if(exp>System.currentTimeMillis()/1000+30)return true;}catch(Exception ignored){}String rt=secure.get("refreshToken");if(rt.isEmpty())return false;R r=http("POST",cloudUrl+"/auth/v1/token?grant_type=refresh_token",json("refresh_token",rt),Collections.singletonMap("apikey",anonKey),null,null);if(r.code>=200&&r.code<300)try{return saveSession(new JSONObject(r.body),secure.get("email"));}catch(Exception ignored){}if(r.code==400||r.code==401)clearCloudAuth();return false;}
  String cloudLogin(String e,String pw){R r=http("POST",cloudUrl+"/auth/v1/token?grant_type=password",json("email",e,"password",pw),Collections.singletonMap("apikey",anonKey),null,null);if(r.code>=200&&r.code<300)try{JSONObject j=new JSONObject(r.body);return saveSession(j,e)?"Angemeldet": "Anmeldung fehlgeschlagen";}catch(Exception ignored){}return error(r);}
  private boolean saveSession(JSONObject j,String email){try{String at=j.optString("access_token"),rt=j.optString("refresh_token");JSONObject u=j.optJSONObject("user");if(at.isEmpty()||rt.isEmpty()||u==null)return false;String uid=u.optString("id");if(uid.isEmpty())return false;String old=secure.get("userId");if(!old.isEmpty()&&!old.equals(uid)){synchronized(p){p.edit().remove("settingsDirty").remove("lastSyncedVoice").remove("lastSyncedCity").apply();}}secure.put("accessToken",at);secure.put("refreshToken",rt);secure.put("expiresAt",j.optString("expires_at",Long.toString(System.currentTimeMillis()/1000+j.optLong("expires_in",3600))));secure.put("userId",u.optString("id"));secure.put("email",u.optString("email",email));return !secure.get("userId").isEmpty();}catch(Exception e){return false;}}
  String cloudSignup(String e,String pw){R r=http("POST",cloudUrl+"/auth/v1/signup",json("email",e,"password",pw),Collections.singletonMap("apikey",anonKey),null,null);if(r.code<200||r.code>=300)return error(r);try{JSONObject j=new JSONObject(r.body);if(j.optString("access_token").isEmpty())return "Registrierung erfolgreich – E-Mail bestätigen";return saveSession(j,e)?"Angemeldet":"Registrierung erfolgreich – E-Mail bestätigen";}catch(Exception x){return "Registrierung erfolgreich – E-Mail bestätigen";}}
  private void clearCloudAuth(){for(String n:new String[]{"accessToken","refreshToken","expiresAt","userId","email"})secure.remove(n);synchronized(p){p.edit().remove("settingsDirty").remove("lastSyncedVoice").remove("lastSyncedCity").apply();}}
  void cloudLogout(){String token=secure.get("accessToken");clearCloudAuth();if(!token.isEmpty()){Map<String,String> h=new HashMap<>();h.put("apikey",anonKey);h.put("Authorization","Bearer "+token);http("POST",cloudUrl+"/auth/v1/logout",null,h,null,null);}}

  void saveLocalSettings(String voice,String city){synchronized(p){p.edit().putString("voice",voice).putString("city",city).putBoolean("settingsDirty",true).apply();}}
  static JSONObject settingsPatch(String voice,String city,String oldVoice,String oldCity)throws JSONException{JSONObject patch=new JSONObject();if(!voice.equals(oldVoice))patch.put("voice",voice);if(!city.equals(oldCity))patch.put("weatherCity",city);return patch;}
  private boolean validSettings(JSONObject x){try{if(x.has("voice")&&(!(x.get("voice") instanceof String)||!x.getString("voice").matches("[A-Za-z][A-Za-z0-9_-]{0,63}")))return false;if(x.has("weatherCity")&&(!(x.get("weatherCity") instanceof String)||x.getString("weatherCity").trim().isEmpty()||x.getString("weatherCity").length()>200))return false;return true;}catch(Exception e){return false;}}
  void syncSettings(){
    if(!hasCloudSession())return;
    synchronized(syncLock){if(syncInFlight)return;syncInFlight=true;}
    new Thread(()->{try{
      String uid=secure.get("userId"),voice,city;boolean dirty;JSONObject patch;
      synchronized(p){dirty=p.getBoolean("settingsDirty",false);voice=p.getString("voice",DEFAULT_VOICE);city=p.getString("city",DEFAULT_CITY);patch=settingsPatch(voice,city,p.getString("lastSyncedVoice",""),p.getString("lastSyncedCity",""));if(dirty&&patch.length()==0){p.edit().putBoolean("settingsDirty",false).apply();dirty=false;}}
      Map<String,String> h=headers();if(!uid.equals(secure.get("userId")))return;
      JSONObject remote;
      if(dirty){R r=http("POST",cloudUrl+"/rest/v1/rpc/jarvis_merge_settings",new JSONObject().put("p_patch",patch).toString(),h,null,null);if(r.code<200||r.code>=300)return;remote=new JSONObject(r.body);}
      else{R r=http("GET",cloudUrl+"/rest/v1/jarvis_profiles?select=id,settings&id=eq."+URLEncoder.encode(uid,"UTF-8")+"&limit=1",null,h,null,null);if(r.code<200||r.code>=300)return;JSONArray rows=new JSONArray(r.body);if(rows.length()==0)return;remote=rows.getJSONObject(0).optJSONObject("settings");}
      if(remote==null||!validSettings(remote)||!uid.equals(secure.get("userId")))return;
      synchronized(p){
        if(!dirty&&p.getBoolean("settingsDirty",false))return;
        boolean changedVoice=dirty&&!voice.equals(p.getString("voice",DEFAULT_VOICE)),changedCity=dirty&&!city.equals(p.getString("city",DEFAULT_CITY));
        SharedPreferences.Editor ed=p.edit();
        if(remote.has("voice")){String v=remote.getString("voice");ed.putString("lastSyncedVoice",v);if(!changedVoice)ed.putString("voice",v);}
        if(remote.has("weatherCity")){String v=remote.getString("weatherCity");ed.putString("lastSyncedCity",v);if(!changedCity)ed.putString("city",v);}
        ed.putBoolean("settingsDirty",changedVoice||changedCity).apply();
      }
    }catch(Exception ignored){}finally{synchronized(syncLock){syncInFlight=false;}}}).start();
  }
  void syncProfile(){syncSettings();}
  boolean cloudConfigured(){return cloudUrl.startsWith("https://")&&!anonKey.isEmpty();}
  void speak(String text,String voice,SpeakCallback cb){if(!isPaired()){cb.done(null,"Für Microsoft-Stimmen mit PC koppeln");return;}new Thread(()->{R r=desktop("POST","/speak",json("text",text,"voice",voice));try{if(r.code<200||r.code>=300)throw new Exception(error(r));JSONObject j=new JSONObject(r.body);String b=j.optString("audio");if(b.isEmpty())throw new Exception("Audio fehlt");cb.done(new SpeakResult(Base64.getDecoder().decode(b),j.optString("mime","audio/mpeg")),null);}catch(Exception e){cb.done(null,e.getMessage());}}).start();}
  String json(String...kv){try{JSONObject j=new JSONObject();for(int i=0;i+1<kv.length;i+=2)j.put(kv[i],kv[i+1]);return j.toString();}catch(Exception e){return "{}";}}
  String error(R r){try{JSONObject j=new JSONObject(r.body);return j.optString("msg",j.optString("message",j.optString("error_description","Fehler ("+r.code+")")));}catch(Exception e){return "Fehler ("+r.code+")";}}
}
